-- legal_search_mock labor_dispute_2026 — init.sql
-- A synthesized labor dispute research corpus for a litigation benchmark:
--   • 6 courts/arbitration commissions across Shanghai/Beijing
--   • 2 statutes: Labor Contract Law + Labor Law, with their key articles (full statutory text simplified, public-domain style)
--   • 18 anonymized labor-dispute judgments (unlawful termination/overtime pay/double wages for unsigned contract/economic compensation/annual leave/non-compete restriction ...)
--   • citation links from cases → statute articles (and a few case→case references)
--   • seeded user usr_li_wei with 2 saved cases + notes (preparing labor arbitration/litigation)
-- All party names anonymized (Zhang/Li). All text original/synthesized.
-- Reference date: 2026-05-20 (task-level only; the server has no clock).

BEGIN;

-- ── Courts / Arbitration Commissions ─────────────────────────────────────────────
INSERT INTO courts (court_id, name, level, region) VALUES
  ('court_sh_pudong',   'Pudong New Area People''s Court of Shanghai',       'basic-level court',   'Shanghai Pudong New Area'),
