  ('court_sh_no1',      'Shanghai No.1 Intermediate People''s Court',       'intermediate court',   'Shanghai'),
  ('court_sh_high',     'Shanghai High People''s Court',           'high court',   'Shanghai'),
  ('court_bj_chaoyang', 'Chaoyang District People''s Court of Beijing',         'basic-level court',   'Beijing Chaoyang District'),
  ('arb_sh_pudong',     'Pudong New Area Labor and Personnel Dispute Arbitration Commission of Shanghai', 'arbitration commission', 'Shanghai Pudong New Area');

-- ── Statutes ───────────────────────────────────────────────────────
INSERT INTO statutes (statute_id, name, short_name, issuer, effective_date, status, summary) VALUES
  ('stat_lcl',  'Labor Contract Law of the People''s Republic of China', 'Labor Contract Law', 'Standing Committee of the National People''s Congress', '2008-01-01', 'currently effective',
    'Regulates the formation, performance, modification, rescission and termination of labor contracts, defines the rights and obligations of employers and employees, and includes core provisions on double wages for failure to conclude a written labor contract, compensation for unlawful termination, and economic compensation.'),
  ('stat_ll',   'Labor Law of the People''s Republic of China', 'Labor Law', 'Standing Committee of the National People''s Congress', '1995-01-01', 'currently effective',
    'The basic law regulating labor relations, providing for working hours, rest and leave, wages, remuneration for extended working hours, and the basic mechanisms for handling labor disputes.');

-- ── Statute articles ─────────────────────────────────────────
-- Labor Contract Law key articles
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES
  ('art_lcl_010', 'stat_lcl', 'Article 10',     10, 'Conclusion of written labor contract',
    'Where a labor relationship is established, a written labor contract shall be concluded. Where a labor relationship has been established but a written labor contract was not concluded at the same time, a written labor contract shall be concluded within one month from the date the employee begins work.'),
  ('art_lcl_036', 'stat_lcl', 'Article 36', 36, 'Termination by mutual agreement',
    'An employer and an employee may rescind the labor contract upon reaching agreement through consultation.'),
  ('art_lcl_038', 'stat_lcl', 'Article 38', 38, 'Unilateral termination by the employee',
    'Where an employer fails to provide labor protection or working conditions as agreed in the labor contract, fails to pay labor remuneration in full and on time, or fails to pay social insurance premiums as required by law, the employee may rescind the labor contract.'),
  ('art_lcl_039', 'stat_lcl', 'Article 39', 39, 'Unilateral termination by the employer (for cause)',
    'Where an employee is proved during the probation period to be unqualified for the position, seriously violates the employer''s rules and regulations, or commits serious dereliction of duty causing major damage to the employer, the employer may rescind the labor contract.'),
  ('art_lcl_040', 'stat_lcl', 'Article 40',   40, 'Dismissal without fault',
    'Under any of the following circumstances, an employer may rescind the labor contract after giving the employee 30 days'' prior written notice or paying the employee an additional one month''s wages: the employee is ill or sustains a non-work-related injury and, after the medical treatment period, is unable to perform the original work; the employee is incompetent and remains incompetent after training or reassignment; or a major change in objective circumstances makes performance of the contract impossible.'),
  ('art_lcl_046', 'stat_lcl', 'Article 46', 46, 'Economic compensation',
    'Under any of the following circumstances, the employer shall pay economic compensation to the employee: the contract is rescinded under Article 38; the employer proposes termination by mutual agreement; the contract is rescinded under Article 40 or Article 41; or the labor contract expires and is terminated.'),
  ('art_lcl_047', 'stat_lcl', 'Article 47', 47, 'Calculation of economic compensation',
    'Economic compensation is paid to the employee at the rate of one month''s wages for each full year of service with the employer. A period of six months or more but less than one year is counted as one year; a period of less than six months entitles the employee to economic compensation of half a month''s wages.'),
  ('art_lcl_048', 'stat_lcl', 'Article 48', 48, 'Consequences of unlawful termination',
    'Where an employer rescinds or terminates a labor contract in violation of this Law, and the employee requests continued performance, the employer shall continue performance; where the employee does not request continued performance or the contract can no longer be performed, the employer shall pay compensation in accordance with Article 87.'),
  ('art_lcl_082', 'stat_lcl', 'Article 82', 82, 'Double wages for failure to sign a written contract',
    'Where an employer fails to conclude a written labor contract with an employee within a period of more than one month but less than one year from the date the employee begins work, the employer shall pay the employee double wages each month.'),
  ('art_lcl_087', 'stat_lcl', 'Article 87', 87, 'Compensation for unlawful termination',
    'Where an employer rescinds or terminates a labor contract in violation of this Law, it shall pay the employee compensation at twice the rate of economic compensation provided in Article 47.');

-- Labor Law key articles
INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES
  ('art_ll_036', 'stat_ll', 'Article 36', 36, 'Working hours system',
    'The State applies a working hours system under which an employee''s working hours shall not exceed eight hours per day and, on average, forty-four hours per week.'),
  ('art_ll_041', 'stat_ll', 'Article 41', 41, 'Limits on extended working hours',
    'Where an employer needs to extend working hours due to production or business needs, it may do so after consulting with the trade union and the employees, generally for no more than one hour per day; for special reasons, no more than three hours per day and no more than thirty-six hours per month.'),
  ('art_ll_044', 'stat_ll', 'Article 44', 44, 'Overtime pay',
    'Where an employee is required to work extended hours, remuneration of no less than 150 percent of the wages shall be paid; where work is arranged on rest days and no compensatory leave can be arranged, remuneration of no less than 200 percent of the wages shall be paid; where work is arranged on statutory holidays, remuneration of no less than 300 percent of the wages shall be paid.'),
  ('art_ll_050', 'stat_ll', 'Article 50', 50, 'Payment of wages',
    'Wages shall be paid to the employee in monetary form on a monthly basis, and shall not be deducted or withheld without cause.');

-- ── Cases (anonymized judgments) ────────────────────────────────────
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES
  ('case_001', '(2025) Hu 0115 Civil First-Instance No. 12001', 'Zhang v. a technology company, dispute over compensation for unlawful termination of labor contract', 'court_sh_pudong', 'labor dispute', 'unlawful termination of labor contract', '2025-11-18',
    'Plaintiff: Zhang (employee); Defendant: a technology company',
    'The company unilaterally rescinded the labor contract citing "organizational restructuring" without providing a lawful basis; the court found this constituted unlawful termination and ordered payment of compensation.',
    'Zhang joined the defendant company in March 2019 as a product manager with a monthly salary of RMB 25000. In June 2025 the company orally notified him of termination citing organizational restructuring, without giving 30 days'' written notice or paying payment in lieu of notice. Zhang claimed unlawful termination and demanded compensation at 2N.',
    'The employer claimed termination under Article 40, but failed to prove a major change in objective circumstances and failed to follow the procedure of prior notice or an additional month''s wages; the termination did not meet the statutory circumstances, constituted unlawful termination, and compensation at twice the economic compensation standard should be paid under Articles 48 and 87.',
    'Where an employer rescinds a labor contract citing "organizational restructuring" but cannot prove the circumstances of Article 40 are met and does not follow the statutory procedure, the termination is unlawful and compensation shall be paid.',
    '1. The defendant shall pay the plaintiff Zhang compensation of RMB 325000 for unlawful termination within ten days of this judgment taking effect (25000 yuan x 6.5 years x 2); 2. The plaintiff''s other claims are dismissed.',
    'upheld', 'unlawful termination,compensation,2N,organizational restructuring,product manager'),

  ('case_002', '(2025) Hu 0112 Civil First-Instance No. 08842', 'Li v. a catering company, dispute over overtime pay', 'court_sh_minhang', 'labor dispute', 'Overtime pay', '2025-09-22',
    'Plaintiff: Li (employee); Defendant: a catering company',
    'The employee worked overtime on rest days for a long period and the company failed to pay overtime in full; the court, relying on attendance records, ordered payment of double overtime pay for rest days.',
    'Li joined the defendant in 2022 as a store manager with an agreed monthly salary of RMB 9000 under the standard working hours system. Attendance records showed 52 days of rest-day overtime in 2024, for which the company arranged no compensatory leave and paid no overtime.',
    'Under Article 44 of the Labor Law, where work is arranged on rest days and no compensatory leave can be arranged, overtime pay of no less than 200 percent shall be paid. The defendant failed to produce evidence of arranged compensatory leave or paid overtime, and shall bear the consequence of failing to discharge its burden of proof.',
    'Where an employer arranges rest-day overtime and cannot arrange compensatory leave, it shall pay overtime of no less than 200 percent of wages; where the employer possesses the attendance records but refuses to produce them, it shall bear the adverse consequence.',
    '1. The defendant shall pay the plaintiff Li rest-day overtime of RMB 43034 for 2024; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'overtime pay,rest days,double wages,attendance,burden of proof'),

  ('case_003', '(2025) Hu 0115 Civil First-Instance No. 09931', 'Wang v. a trading company, dispute over double wages for failure to sign a labor contract', 'court_sh_pudong', 'labor dispute', 'failure to sign a written labor contract', '2025-08-30',
    'Plaintiff: Wang (employee); Defendant: a trading company',
    'The company employed the employee for more than one month without signing a written labor contract; the court ordered payment of the double-wage difference for the period without a signed contract.',
    'Wang joined the defendant as a salesperson on 1 September 2024 without signing a written labor contract. He worked until leaving in May 2025 at a monthly salary of RMB 12000. Wang claimed double wages from 1 October 2024 until his departure.',
    'Under Articles 10 and 82 of the Labor Contract Law, where no written labor contract is concluded for more than one month but less than one year, double wages shall be paid each month from the second month. The limitation period for the double-wage claim runs from the date the right is asserted, and it had not expired in this case.',
    'Where an employer fails to conclude a written labor contract for more than one month from the date the employee begins work, it shall pay double wages monthly from the second month, for no more than eleven months.',
    '1. The defendant shall pay the plaintiff Wang the double-wage difference of RMB 96000 for failure to sign a written labor contract for the period 1 October 2024 to May 2025; 2. The remaining claims are dismissed.',
    'upheld', 'unsigned labor contract,double wages,Article 82,limitation period,salesperson'),

  ('case_004', '(2025) Hu 0112 Civil First-Instance No. 07765', 'Zhao v. a manufacturing company, dispute over economic compensation', 'court_sh_minhang', 'labor dispute', 'Economic compensation', '2025-07-15',
    'Plaintiff: Zhao (employee); Defendant: a manufacturing company',
    'The company failed to pay social insurance as required by law; the employee accordingly rescinded the labor contract and claimed economic compensation, which the court upheld.',
    'Zhao joined the defendant in 2017 at a monthly salary of RMB 8000. From 2023 the defendant failed to pay his social insurance premiums in full. In March 2025 Zhao gave written notice of termination citing the failure to pay social insurance and claimed economic compensation.',
    'Under Article 38 of the Labor Contract Law, where an employer fails to pay social insurance premiums for an employee as required by law, the employee may rescind the contract; under Articles 46 and 47, the employer shall pay economic compensation, with the period of service counted as eight years.',
    'Where an employer fails to pay social insurance premiums and the employee rescinds the labor contract on that ground, the employee is entitled to claim economic compensation (N) under Article 46, rather than compensation for unlawful termination.',
    '1. The defendant shall pay the plaintiff Zhao economic compensation of RMB 64000 (8000 yuan x 8 years); 2. The case acceptance fee, reduced by half, shall be borne by the defendant.',
    'upheld', 'economic compensation,N,termination under pressure,unpaid social insurance,Article 38'),

  ('case_005', '(2025) Hu 01 Civil Appeal No. 04421', 'A network company v. Liu, appeal over dispute of unlawful termination of labor contract', 'court_sh_no1', 'labor dispute', 'unlawful termination of labor contract', '2025-10-09',
    'Appellant: a network company; Appellee: Liu (employee)',
    'The company terminated for "serious violation of rules and regulations", but the rules had not been adopted through democratic procedures nor publicized; the second-instance court found the termination unlawful and affirmed the compensation judgment.',
    'Liu joined the defendant in 2020 as an operations staff member at a monthly salary of RMB 18000. In 2025 the company terminated him for "attendance irregularities seriously violating the rules and regulations". The attendance management rules the company submitted had not been discussed by the employee representatives'' congress nor publicized to Liu. The first-instance court found the termination unlawful, and the company appealed.',
    'Under Article 39 of the Labor Contract Law, termination for serious violation of rules and regulations presupposes that the rules are lawful and effective. The rules at issue were not adopted through democratic procedures nor publicized to the employee, and could not serve as the basis for termination; the termination was unlawful and compensation shall be paid.',
    'Where an employer rescinds a labor contract for "serious violation of rules and regulations", the rules relied on must be adopted through democratic procedures and publicized to the employee, otherwise they cannot serve as the basis for termination.',
    '1. The appeal is dismissed and the original judgment is affirmed (the defendant shall pay Liu compensation of RMB 180000 for unlawful termination); 2. The second-instance case acceptance fee shall be borne by the appellant.',
    'dismissed', 'unlawful termination,rules and regulations,democratic procedures,publication,compensation,operations'),

  ('case_006', '(2025) Hu 0115 Civil First-Instance No. 10210', 'Chen v. a consulting company, dispute over overtime pay and wages for untaken annual leave', 'court_sh_pudong', 'labor dispute', 'Overtime pay', '2025-06-28',
    'Plaintiff: Chen (employee); Defendant: a consulting company',
    'The employee worked extended hours on workdays and did not take annual leave for two consecutive years; the court ordered payment of extended-hours overtime and wages for untaken annual leave.',
    'Chen joined the defendant in 2021 as a consultant at a monthly salary of RMB 20000 under standard working hours. His 2023-2024 DingTalk clock records showed about 260 hours of extended overtime on workdays, and annual leave was not arranged in either year.',
    'Under Article 44 of the Labor Law, extended working hours on workdays shall be paid overtime of no less than 150 percent; untaken annual leave shall be compensated at 300 percent of daily wages. Electronic clock records may serve as evidence of overtime.',
    'Where electronic attendance records can prove overtime, the employer shall pay extended-hours overtime accordingly; where annual leave has not been arranged for consecutive years, wages for untaken annual leave shall be paid.',
    '1. The defendant shall pay Chen extended-hours overtime of RMB 43103; 2. The defendant shall pay Chen wages of RMB 22069 for untaken annual leave; 3. The remaining claims are dismissed.',
    'partially upheld', 'overtime pay,extended overtime,annual leave,electronic clock,consultant'),

  ('case_007', '(2025) Jing 0105 Civil First-Instance No. 15580', 'Sun v. an education company, dispute over unlawful termination (during pregnancy)', 'court_bj_chaoyang', 'labor dispute', 'unlawful termination of labor contract', '2025-12-03',
    'Plaintiff: Sun (employee); Defendant: an education company',
    'The company terminated the labor contract during the employee''s pregnancy on the ground of "incompetence" without training or reassignment; the court found the termination unlawful and ordered continued performance.',
    'Sun joined the defendant in 2022 as a teaching-research staff member at a monthly salary of RMB 15000. During her pregnancy in 2025, the company terminated her on the ground that "performance fell short and she was incompetent". The company produced no evidence of training or reassignment.',
    'Under Article 40 of the Labor Contract Law, termination for incompetence requires that the employee remain incompetent after training or reassignment; moreover, pregnant employees enjoy special protection and the employer may not terminate under Article 40. The termination was unlawful, and as Sun requested continued performance, the contract shall continue to be performed under Article 48.',
    'During pregnancy, maternity, or breastfeeding, an employer may not rescind the labor contract on the ground of incompetence; where the employee requests continued performance, performance shall continue.',
    '1. The defendant''s termination of the labor contract is confirmed unlawful; 2. The parties shall continue performing the labor contract, and the defendant shall pay Sun wages from the date of termination until her return to work.',
    'upheld', 'unlawful termination,pregnancy,three-period female employee,continued performance,incompetence'),

  ('case_008', '(2025) Hu 0112 Civil First-Instance No. 06012', 'Zhou v. a logistics company, dispute over wage arrears', 'court_sh_minhang', 'labor dispute', 'arrears of labor remuneration', '2025-05-19',
    'Plaintiff: Zhou (employee); Defendant: a logistics company',
    'The company was in wage arrears for three consecutive months; the employee claimed the arrears and termination compensation, and the court upheld the wage portion.',
    'Zhou joined the defendant in 2023 as a driver at a monthly salary of RMB 7500. From January 2025 the defendant failed to pay wages for three consecutive months. Zhou accordingly rescinded the labor contract and claimed the arrears and economic compensation.',
    'Under Article 50 of the Labor Law and Article 38 of the Labor Contract Law, an employer that withholds wages without cause shall pay them in full, and the employee may rescind the contract and claim economic compensation on that ground. The defendant did not dispute the arrears.',
    'Where an employer withholds labor remuneration without cause, it shall pay in full, and the employee who rescinds the labor contract on that ground is entitled to claim economic compensation.',
    '1. The defendant shall pay Zhou wage arrears of RMB 22500; 2. The defendant shall pay Zhou economic compensation of RMB 15000.',
    'upheld', 'wage arrears,unpaid wages,termination under pressure,economic compensation,driver'),

  ('case_009', '(2025) Hu 0115 Civil First-Instance No. 11876', 'Wu v. a financial company, dispute over non-compete compensation', 'court_sh_pudong', 'labor dispute', 'non-compete restriction', '2025-10-27',
    'Plaintiff: Wu (employee); Defendant: a financial company',
    'The parties agreed on a non-compete restriction but the company paid no compensation; the employee claimed compensation, and the court ordered monthly payment of the non-compete economic compensation.',
    'Wu joined the defendant in 2021 as an R&D supervisor at a monthly salary of RMB 30000 and signed a one-year non-compete agreement on departure. After leaving, Wu complied with the non-compete obligation, but the defendant paid no compensation.',
    'During the non-compete period the employer shall pay monthly economic compensation; where no amount is agreed, it shall be paid monthly at 30 percent of the employee''s average wage over the twelve months before departure, and no less than the minimum wage standard.',
    'Where a non-compete restriction is agreed without agreeing on economic compensation, the employee who has performed the obligation is entitled to claim monthly compensation at 30 percent of the average monthly wage before departure.',
    '1. The defendant shall pay Wu non-compete economic compensation of RMB 108000 (30000 yuan x 30% x 12 months); 2. The remaining claims are dismissed.',
    'partially upheld', 'non-compete restriction,compensation,R&D supervisor,30 percent,departure'),

  ('case_010', '(2025) Hu 0112 Civil First-Instance No. 05533', 'Zheng v. a retail company, dispute over termination during probation', 'court_sh_minhang', 'labor dispute', 'unlawful termination of labor contract', '2025-04-11',
    'Plaintiff: Zheng (employee); Defendant: a retail company',
    'The company terminated during probation on the ground of "failure to meet hiring conditions", but the hiring conditions were not specified and there was no assessment basis; the court found the termination unlawful.',
    'Zheng joined the defendant in January 2025 as a store clerk with an agreed three-month probation period. In the second month the company terminated him for "failure to meet hiring conditions", but had not specified the hiring conditions at hiring and had no assessment records.',
    'Under Article 39 of the Labor Contract Law, termination for failure to meet hiring conditions during probation requires the employer to have specified the hiring conditions in advance and to prove the employee''s non-compliance. The defendant failed to discharge its burden, constituting unlawful termination.',
    'Where an employer rescinds a labor contract for failure to meet hiring conditions during probation, it shall have specified the hiring conditions in advance and bear the burden of proving the employee''s non-compliance.',
    '1. The defendant shall pay Zheng compensation of RMB 6000 for unlawful termination; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unlawful termination,probation period,hiring conditions,burden of proof,store clerk'),

  ('case_011', '(2024) Hu 0115 Civil First-Instance No. 21344', 'Feng v. an advertising company, dispute over double wages for failure to sign a labor contract', 'court_sh_pudong', 'labor dispute', 'failure to sign a written labor contract', '2024-12-20',
    'Plaintiff: Feng (employee); Defendant: an advertising company',
    'The company employed the employee for nearly a year without a written contract; the court ordered payment of the eleven-month double-wage difference.',
    'Feng joined the defendant in June 2023 as a designer at a monthly salary of RMB 14000 and never signed a written labor contract until leaving in June 2024. Feng claimed double wages for the unsigned contract.',
    'Under Article 82 of the Labor Contract Law, double wages for failure to sign a written labor contract are paid for at most eleven months, running from the day after one full month of employment.',
    'The double-wage period for failure to conclude a written labor contract is at most eleven months, starting from the day after one full month from the date the employee begins work.',
    '1. The defendant shall pay Feng the double-wage difference of RMB 154000 for failure to sign a written labor contract; 2. The remaining claims are dismissed.',
    'upheld', 'unsigned labor contract,double wages,eleven months,designer,Article 82'),

  ('case_012', '(2025) Hu 0112 Civil First-Instance No. 06890', 'Jiang v. a technology company, dispute over the base for calculating economic compensation', 'court_sh_minhang', 'labor dispute', 'Economic compensation', '2025-06-05',
    'Plaintiff: Jiang (employee); Defendant: a technology company',
    'The parties disputed whether bonuses should be included in the base for calculating economic compensation; the court held the base should be the average wage over the twelve months before departure.',
    'Jiang joined the defendant in 2018 with a fixed monthly salary of RMB 16000 plus an annual performance bonus. On termination by agreement in 2025, the company calculated economic compensation using only the base salary. Jiang claimed the bonus should be included.',
    'Under Article 47 of the Labor Contract Law, the monthly wage for economic compensation means the employee''s average wage over the twelve months before rescission of the labor contract, including bonuses, allowances, and other monetary income.',
    'The monthly wage base for economic compensation shall be the employee''s average earned wage over the twelve months before termination, including bonuses and allowances, rather than merely the base salary.',
    '1. The defendant shall pay Jiang the economic compensation difference of RMB 28000; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'economic compensation,calculation base,average wage,bonus,Article 47'),

  ('case_013', '(2025) Hu 0115 Civil First-Instance No. 10044', 'Han v. a pharmaceutical company, dispute over overtime pay (comprehensive working hours)', 'court_sh_pudong', 'labor dispute', 'Overtime pay', '2025-09-08',
    'Plaintiff: Han (employee); Defendant: a pharmaceutical company',
    'The company claimed to apply a comprehensive working hours system without approval; the court applied the standard working hours system and awarded overtime pay.',
    'Han joined the defendant in 2022 as a sales representative at a monthly salary of RMB 13000. The company claimed the comprehensive working hours system meant no overtime was payable, but produced no evidence of approval by the human resources department.',
    'An employer applying the comprehensive working hours system must obtain approval from the labor administrative authority. Without approval, overtime shall be calculated and paid under the standard working hours system.',
    'Where an employer claims to apply the comprehensive working hours system without approval from the labor administrative authority, overtime shall be calculated and paid under the standard working hours system.',
    '1. The defendant shall pay Han overtime of RMB 31494; 2. The remaining claims are dismissed.',
    'partially upheld', 'overtime pay,comprehensive working hours,approval,standard working hours,sales representative'),

  ('case_014', '(2025) Jing 0105 Civil First-Instance No. 12233', 'Yang v. an internet company, dispute over unlawful termination (rank-and-yank)', 'court_bj_chaoyang', 'labor dispute', 'unlawful termination of labor contract', '2025-08-14',
    'Plaintiff: Yang (employee); Defendant: an internet company',
    'The company terminated the labor contract through "rank-and-yank"; the court held that ranking last is not equivalent to incompetence and the termination was unlawful.',
    'Yang joined the defendant in 2020 as an engineer at a monthly salary of RMB 28000. In 2025 the company terminated him for ranking last in performance. The company did not prove incompetence and provided no training or reassignment.',
    '"Rank-and-yank" is not a statutory ground for termination. Ranking last in performance is not equivalent to incompetence; an employer that terminates on this ground without training or reassignment commits unlawful termination.',
    'Where an employer rescinds a labor contract through performance "rank-and-yank", because ranking last is not equivalent to incompetence, the termination is unlawful and compensation shall be paid.',
    '1. The defendant shall pay Yang compensation of RMB 280000 for unlawful termination; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unlawful termination,rank-and-yank,incompetence,compensation,engineer'),

  ('case_015', '(2025) Hu 0112 Civil First-Instance No. 07120', 'Zhu v. a construction company, dispute over wages during the work-injury suspension period', 'court_sh_minhang', 'labor dispute', 'arrears of labor remuneration', '2025-07-02',
    'Plaintiff: Zhu (employee); Defendant: a construction company',
    'The company stopped paying wages during the employee''s work-injury suspension period; the court ordered back payment of wages during the suspension period at the original wage standard.',
    'Zhu joined the defendant in 2020 as a worker at a monthly salary of RMB 6500. He was injured at work in 2024 and the injury was recognized as a work-related injury, but the company paid no wages during the six-month suspension period.',
    'Where an employee needs to suspend work for treatment due to a work-related injury, the original wages and benefits remain unchanged during the suspension period and are paid monthly by the employer.',
    'During the work-injury suspension period, the employer shall pay monthly wages at the original wage and benefit standard and shall not stop payment.',
    '1. The defendant shall pay Zhu wages of RMB 39000 for the suspension period; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'work-related injury,suspension period,wages,original wage standard,worker'),

  ('case_016', '(2025) Hu 0115 Civil First-Instance No. 09015', 'He v. a technology company, dispute over compensation for unlawful termination', 'court_sh_pudong', 'labor dispute', 'unlawful termination of labor contract', '2025-05-26',
    'Plaintiff: He (employee); Defendant: a technology company',
    'The company terminated citing "major change in objective circumstances" but did not consult the employee about amending the contract; the court found the termination unlawful.',
    'He joined the defendant in 2016 as a senior engineer at a monthly salary of RMB 32000. In 2025 the company terminated him on the ground that the business adjustment was a "major change in objective circumstances", but did not first consult He about amending the labor contract.',
    'Under Article 40 of the Labor Contract Law, termination due to a major change in objective circumstances making performance impossible requires first consulting the employee about amending the contract without reaching agreement. The defendant did not follow the consultation procedure, constituting unlawful termination.',
    'Where a labor contract is terminated on the ground of "major change in objective circumstances", the employer shall first consult the employee about amending the contract; termination without such consultation constitutes unlawful termination.',
    '1. The defendant shall pay He compensation of RMB 608000 for unlawful termination (32000 yuan x 9.5 years x 2); 2. The remaining claims are dismissed.',
    'upheld', 'unlawful termination,major change in objective circumstances,consultation on amendment,compensation,senior engineer'),

  ('case_017', '(2024) Hu 0115 Civil First-Instance No. 19922', 'Lu v. a technology company, dispute over compensation for unlawful termination (redundancy without preferential retention)', 'court_sh_pudong', 'labor dispute', 'unlawful termination of labor contract', '2024-11-30',
    'Plaintiff: Lu (employee); Defendant: a technology company',
    'In an economic redundancy, the company failed to preferentially retain employees with longer-term contracts and did not report to the labor authority; the court found the procedure unlawful.',
    'Lu joined the defendant in 2015 as a test engineer under an open-ended labor contract at a monthly salary of RMB 22000. In the 2024 redundancy the company laid him off without preferentially retaining open-ended-contract employees and without reporting the redundancy plan to the labor administrative authority.',
    'Under Article 41 of the Labor Contract Law, economic redundancies shall preferentially retain employees with open-ended labor contracts and shall be reported to the labor administrative authority in advance. The defendant''s procedure was unlawful, constituting unlawful termination.',
    'Where an employer''s economic redundancy fails to preferentially retain open-ended-contract employees and is not reported to the labor administrative authority, the redundancy procedure is unlawful and constitutes unlawful termination.',
    '1. The defendant shall pay Lu compensation of RMB 418000 for unlawful termination; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unlawful termination,economic redundancy,preferential retention,open-ended contract,unlawful procedure'),

  ('case_018', '(2025) Hu 01 Civil Appeal No. 05012', 'A technology company v. Qian, appeal over dispute of non-compete liquidated damages', 'court_sh_no1', 'labor dispute', 'non-compete restriction', '2025-11-05',
    'Appellant: a technology company; Appellee: Qian (employee)',
    'The company claimed the employee breached the non-compete restriction and demanded high liquidated damages; the second-instance court found the damages excessive and reduced them.',
    'Qian joined the defendant in 2019 as an algorithm engineer and on departure agreed to non-compete liquidated damages of three times his annual salary, totaling RMB 1.8 million. The company claimed he joined a competitor and demanded payment. The first-instance court reduced the damages. The company appealed for the full amount.',
    'Where non-compete liquidated damages are agreed to be grossly excessive relative to actual loss, the employee may request an appropriate reduction. Considering the compensation amount, the circumstances of the breach, and the actual loss, the first-instance reduction was not improper.',
    'Where non-compete liquidated damages are grossly excessive relative to the employer''s actual loss, the people''s court may appropriately reduce them upon the party''s request.',
    '1. The appeal is dismissed and the original judgment is affirmed (Qian shall pay non-compete liquidated damages of RMB 360000); 2. The second-instance acceptance fee shall be borne by the appellant.',
    'dismissed', 'non-compete restriction,liquidated damages,reduction,algorithm engineer,actual loss');

