-- ══ Historical labor dispute case library ══
INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES
  ('lcase_001', '(2023) Hu 9000 Civil First-Instance No. 20000', 'Cao v. a technology company, dispute over overtime pay', 'court_sh_xuhui', 'labor dispute', 'Overtime pay', '2023-12-15',
    'Plaintiff: Cao (employee); Defendant: a technology company',
    'The employee worked extended overtime and the company failed to pay overtime in full; the court ordered back payment based on attendance records.',
    'Cao joined the defendant in 2021 as a product operations staff member at a monthly salary of RMB 6000. The employee worked extended overtime and the company failed to pay overtime in full; the court ordered back payment based on attendance records. The attendance-system records and pay slips were cross-examined by both parties at trial.',
    'The employer claimed the irregular working hours system was already applied, but submitted no filing materials approved by the human resources department, so extended-hours remuneration shall still be computed under the standard working hours system. The attendance records generated by the company system and signed by the employee may serve as the basis for finding overtime.',
    'Where a special working hours system is applied without lawful approval, extended-hours remuneration shall be computed under the standard working hours system.',
    '1. The defendant shall pay Cao the relevant amount of RMB 12000; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'overtime pay,extended overtime,attendance,standard working hours'),

  ('lcase_002', '(2023) Hu 9001 Civil First-Instance No. 20037', 'Yan v. an e-commerce company, dispute over economic compensation', 'court_sh_jingan', 'labor dispute', 'Economic compensation', '2023-11-22',
    'Plaintiff: Yan (employee); Defendant: an e-commerce company',
    'The company proposed termination by agreement, and the court ordered economic compensation according to years of service.',
    'Yan joined the defendant in 2020 as a customer-service specialist at a monthly salary of RMB 6350. The company proposed termination by agreement, and the court ordered economic compensation according to years of service. The parties disagreed on the starting point of years of service and each submitted employment materials.',
    'Where the labor contract is terminated by agreement, the company shall pay economic compensation according to the employee''s years of service in the unit. Years of service run from the date of actual employment and include the prior labor-dispatch period, because during that period the employee was assigned by the same employer to work in the same position.',
    'Years of service shall be computed continuously from the date of actual employment, including the dispatch period in the same position.',
    '1. The defendant shall pay Yan the relevant amount of RMB 19050; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'economic compensation,N,termination by agreement,years of service'),

  ('lcase_003', '(2023) Hu 9002 Civil First-Instance No. 20074', 'Hua v. a media company, dispute over failure to sign a written labor contract', 'court_bj_haidian', 'labor dispute', 'failure to sign a written labor contract', '2023-10-01',
    'Plaintiff: Hua (employee); Defendant: a media company',
    'Employment continued for more than one month without a written contract, and the court ordered payment of the double-wage difference.',
    'Hua joined the defendant in 2019 as a front-end engineer at a monthly salary of RMB 6700. Employment continued for more than one month without a written contract, and the court ordered payment of the double-wage difference. The company failed to submit proof that it had requested the employee in writing to sign a contract.',
    'Where no written labor contract is concluded for more than one month but less than one year from the date of employment, the double-wage difference shall be paid, running from the day after one full month of employment until the date a contract is belatedly concluded. The company alleged the employee refused to sign, but submitted no written proof that it had requested signing.',
    'The double-wage difference for failure to conclude a written contract runs from the day after one full month of employment; an employer alleging the employee refused to sign bears the burden of proof.',
    '1. The defendant shall pay Hua the relevant amount of RMB 26800; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unsigned labor contract,double wages,Article 82'),

  ('lcase_004', '(2023) Hu 9003 Civil First-Instance No. 20111', 'Jin v. a manufacturing company, dispute over withheld labor remuneration', 'arb_bj_chaoyang', 'labor dispute', 'arrears of labor remuneration', '2023-09-08',
    'Plaintiff: Jin (employee); Defendant: a manufacturing company',
    'The company withheld wages without cause; the employee rescinded under pressure and claimed back payment, which the court upheld.',
    'Jin joined the defendant in 2018 as a finance specialist at a monthly salary of RMB 7050. The company withheld wages without cause; the employee rescinded under pressure and claimed back payment, which the court upheld. The company submitted no wage payment proof for the months in question.',
    'The company failed to pay wages in full by the date agreed in the labor contract and produced no proof of payment. Wage payment records are kept by the employer; where it fails to discharge its burden of proof, the amount claimed by the employee is accepted.',
    'Wage payment records are kept by the employer; where it fails to discharge its burden of proof, the employee''s claim is accepted.',
    '1. The defendant shall pay Jin the relevant amount of RMB 35250; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'wage arrears,unpaid wages,termination under pressure'),

  ('lcase_005', '(2023) Hu 9004 Civil First-Instance No. 20148', 'Wei v. a logistics company, dispute over non-compete restriction', 'court_sh_pudong', 'labor dispute', 'non-compete restriction', '2023-08-15',
    'Plaintiff: Wei (employee); Defendant: a logistics company',
    'A non-compete restriction was agreed but no compensation was paid; the employee claimed compensation, and the court upheld it at its discretion.',
    'Wei joined the defendant in 2017 as a marketing manager at a monthly salary of RMB 7400. A non-compete restriction was agreed but no compensation was paid; the employee claimed compensation, and the court upheld it at its discretion. The agreement signed by the parties contained no compensation-standard term.',
    'A non-compete term is conditioned on the employer paying monthly economic compensation. Although the parties agreed on the non-compete obligation, no compensation standard was agreed and the company paid nothing; the employee''s request to confirm the term is not binding is upheld.',
    'A non-compete term under which no economic compensation was agreed and none was paid has no binding force on the employee.',
    '1. The defendant shall pay Wei the relevant amount of RMB 44400; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'non-compete restriction,compensation,departure'),

  ('lcase_006', '(2023) Hu 9005 Civil First-Instance No. 20185', 'Tao v. a consulting company, dispute over unlawful termination of labor contract', 'court_sh_minhang', 'labor dispute', 'unlawful termination of labor contract', '2023-07-22',
    'Plaintiff: Tao (employee); Defendant: a consulting company',
    'The company terminated for serious disciplinary violation but the rules had not been publicized, and the court found the termination unlawful.',
    'Tao joined the defendant in 2016 as a warehouse keeper at a monthly salary of RMB 7750. The company terminated unilaterally without following the statutory procedure, and the court found the termination unlawful and awarded compensation. The company submitted no democratic-procedure or publicity materials for the rules and regulations.',
    'The company rescinded the labor contract for serious violation of rules and regulations, but the rules had not been adopted through democratic procedures nor publicized to the employee and could not serve as the basis for termination; the termination was unlawful.',
    'Rules and regulations not adopted through democratic procedures or not publicized to the employee cannot serve as the basis for terminating the labor contract.',
    '1. The defendant shall pay Tao the relevant amount of RMB 54250; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unlawful termination,compensation,unlawful procedure'),

  ('lcase_007', '(2023) Hu 9006 Civil First-Instance No. 20222', 'Jiang v. a catering company, dispute over annual leave', 'court_bj_chaoyang', 'labor dispute', 'annual leave', '2023-06-01',
    'Plaintiff: Jiang (employee); Defendant: a catering company',
    'The company submitted no leave-approval records, and the court deemed leave not arranged and ordered payment of wages for untaken annual leave.',
    'Jiang joined the defendant in 2015 as a quality inspector at a monthly salary of RMB 8100. The employee did not take annual leave for several consecutive years, and the court ordered payment of wages for untaken annual leave. The company submitted no annual leave approval or scheduling records.',
    'Where an employee''s cumulative work reaches one year but less than ten years, annual leave is five days. The company claimed leave had been arranged but submitted no leave-approval records, so leave is deemed not arranged, and remuneration for untaken annual leave shall be paid at 300 percent of daily wages.',
    'Where the employer submits no leave-approval records, annual leave is deemed not arranged, and wages for untaken annual leave shall be paid.',
    '1. The defendant shall pay Jiang the relevant amount of RMB 64800; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'annual leave,wages for untaken annual leave,triple'),

  ('lcase_008', '(2023) Hu 9007 Civil First-Instance No. 20259', 'Qi v. an education company, dispute over social insurance', 'court_sh_xuhui', 'labor dispute', 'social insurance', '2023-05-08',
    'Plaintiff: Qi (employee); Defendant: an education company',
    'The company''s delay in handling social insurance registration prevented the employee from enjoying medical benefits, and the court ordered compensation for the loss.',
    'Qi joined the defendant in 2014 as an administrative assistant at a monthly salary of RMB 8450. The company failed to pay social insurance as required by law; the employee rescinded on that ground and claimed economic compensation. The parties confirmed that the enrollment registration was handled more than thirty days after employment began.',
    'The employer shall handle social insurance registration for the employee within thirty days of employment. The company''s delay prevented the employee from enjoying medical insurance benefits, and it shall compensate the corresponding loss.',
    'Where delay in handling social insurance registration prevents the employee from enjoying benefits, the employer shall compensate the loss.',
    '1. The defendant shall pay Qi the relevant amount of RMB 76050; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'social insurance,back payment,termination under pressure,Article 38'),

  ('lcase_009', '(2023) Hu 9008 Civil First-Instance No. 20296', 'Xie v. a financial company, dispute over work-related injury', 'court_sh_jingan', 'labor dispute', 'work-related injury', '2023-04-15',
    'Plaintiff: Xie (employee); Defendant: a financial company',
    'The employee was injured at work and it was recognized as a work-related injury, and the court ordered the company to pay the corresponding benefits.',
    'Xie joined the defendant in 2013 as a data analyst at a monthly salary of RMB 8800. The company stopped paying wages during the employee''s work-injury suspension period, and the court ordered back payment. The human resources department issued the work-injury recognition decision and the labor-capacity appraisal conclusion.',
    'The employee sustained an accident injury at the workplace during working hours for work reasons; it was recognized as a work-related injury and a disability grade was assessed by the human resources department, and the company shall pay the corresponding benefits at the standard.',
    'Where a work-related injury is recognized and a disability grade is assessed, the employer shall pay the corresponding benefits at the standard.',
    '1. The defendant shall pay Xie the relevant amount of RMB 88000; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'work-related injury,suspension period,wages'),

  ('lcase_010', '(2023) Hu 9009 Civil First-Instance No. 20333', 'Zou v. a trading company, labor arbitration dispute', 'court_bj_haidian', 'labor arbitration', 'labor arbitration', '2023-03-22',
    'Plaintiff: Zou (employee); Defendant: a trading company',
    'For disputes over withheld remuneration during the subsistence of the labor relationship, the court found the one-year limitation period inapplicable.',
    'Zou joined the defendant in 2021 as a project manager at a monthly salary of RMB 9150. The parties reached a mediation settlement during arbitration, and the company paid a one-off compensation. The parties did not dispute the time of termination of the labor relationship.',
    'The limitation period for applying for labor-dispute arbitration is one year, running from the date the party knew or should have known its rights were infringed. Disputes over withheld labor remuneration arising during the subsistence of the labor relationship are not subject to this limitation.',
    'Disputes over withheld labor remuneration arising during the subsistence of the labor relationship are not subject to the one-year arbitration limitation period.',
    '1. The defendant shall pay Zou the relevant amount of RMB 18300; 2. The case acceptance fee shall be borne by the defendant.',
    'mediated', 'labor arbitration,mediation,one-off compensation'),

  ('lcase_011', '(2023) Hu 9010 Civil First-Instance No. 20370', 'Yu v. a technology company, dispute over overtime pay', 'arb_bj_chaoyang', 'labor dispute', 'Overtime pay', '2023-02-01',
    'Plaintiff: Yu (employee); Defendant: a technology company',
    'The company claimed to apply the irregular working hours system without approval, and the court computed extended-hours remuneration under the standard working hours system.',
    'Yu joined the defendant in 2020 as a supply-chain specialist at a monthly salary of RMB 9500. The employee worked extended overtime and the company failed to pay overtime in full; the court ordered back payment based on attendance records. The company submitted the shift schedule, and the employee submitted exported clock-in records.',
    'The company''s shift schedule conflicted with the employee''s clock-in records in several respects; since the employer controls attendance management, the adverse consequence of the burden of proof is borne by it. The overtime hours were determined from the clock-in records after deducting the statutory meal time.',
    'Where the employer controls attendance management and fails to discharge its burden of proof, it bears the adverse consequence.',
    '1. The defendant shall pay Yu the relevant amount of RMB 28500; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'overtime pay,extended overtime,attendance,standard working hours'),

  ('lcase_012', '(2023) Hu 9011 Civil First-Instance No. 20407', 'Bai v. an e-commerce company, dispute over economic compensation', 'court_sh_pudong', 'labor dispute', 'Economic compensation', '2023-01-08',
    'Plaintiff: Bai (employee); Defendant: an e-commerce company',
    'Whether years of service include the dispatch period was disputed, and the court held they should be computed continuously.',
    'Bai joined the defendant in 2019 as a UI designer at a monthly salary of RMB 9850. The company proposed termination by agreement, and the court ordered economic compensation according to years of service. The resignation application submitted by the company bore no signature of the employee.',
    'The company argued the employee resigned voluntarily and thus no compensation was owed, but the resignation application it submitted bore no employee signature, and the termination notice was issued by the company first; it should be treated as termination proposed by the company and agreed upon by consultation.',
    'Where the termination notice was issued by the employer first and the resignation application bears no employee signature, it is treated as termination by agreement.',
    '1. The defendant shall pay Bai the relevant amount of RMB 39400; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'economic compensation,N,termination by agreement,years of service'),

  ('lcase_013', '(2022) Hu 9012 Civil First-Instance No. 20444', 'Shui v. a media company, dispute over failure to sign a written labor contract', 'court_sh_minhang', 'labor dispute', 'failure to sign a written labor contract', '2022-12-15',
    'Plaintiff: Shui (employee); Defendant: a media company',
    'The contract signature did not match the person''s handwriting upon comparison, and the court found no written labor contract was lawfully concluded.',
    'Shui joined the defendant in 2017 as a test engineer at a monthly salary of RMB 10200. Employment continued for more than one month without a written contract, and the court ordered payment of the double-wage difference. During the proceedings, the contract signature was compared against the handwriting.',
    'The employee''s signature on the labor contract submitted by the company did not match his own handwriting upon comparison; it should be found that no written labor contract was lawfully concluded, and the double-wage difference is supported.',
    'Where the signature on the contract does not match the person''s own handwriting upon comparison, it is found that no written labor contract was lawfully concluded.',
    '1. The defendant shall pay Shui the relevant amount of RMB 51000; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unsigned labor contract,double wages,Article 82'),

  ('lcase_014', '(2022) Hu 9013 Civil First-Instance No. 20481', 'Dou v. a manufacturing company, dispute over withheld labor remuneration', 'court_bj_chaoyang', 'labor dispute', 'arrears of labor remuneration', '2022-11-22',
    'Plaintiff: Dou (employee); Defendant: a manufacturing company',
    'The company offset wages against losses caused by the employee, and the court found the offset not supportable.',
    'Dou joined the defendant in 2016 as a sales consultant at a monthly salary of RMB 10550. The company withheld wages without cause; the employee rescinded under pressure and claimed back payment, which the court upheld. The parties disagreed on the amount of loss and the basis for offsetting.',
    'The company claimed to offset wages against losses caused by the employee, but without consultation and without an effective judgment confirming the amount of loss, and where the deduction would fall below the local minimum wage, the offset is not supported.',
    'Without consultation and without an effective judgment confirming the loss, no deduction may be made from wages, and the amount after deduction may not fall below the minimum wage standard.',
    '1. The defendant shall pay Dou the relevant amount of RMB 63300; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'wage arrears,unpaid wages,termination under pressure'),

  ('lcase_015', '(2022) Hu 9014 Civil First-Instance No. 20518', 'Zhang v. a logistics company, dispute over non-compete restriction', 'court_sh_xuhui', 'labor dispute', 'non-compete restriction', '2022-10-01',
    'Plaintiff: Zhang (employee); Defendant: a logistics company',
    'The company failed to pay non-compete compensation for three months, and the court upheld the employee''s rescission of the non-compete agreement.',
    'Zhang joined the defendant in 2015 as an HR specialist at a monthly salary of RMB 10900. A non-compete restriction was agreed but no compensation was paid; the employee claimed compensation, and the court upheld it at its discretion. The company confirmed it did not actually pay non-compete compensation after termination.',
    'Where the company fails to pay non-compete compensation within three months after termination of the labor contract, the employee''s request to rescind the non-compete agreement on that ground is consistent with law and is upheld.',
    'Where the employer fails to pay non-compete compensation for three months, the employee may request rescission of the non-compete agreement.',
    '1. The defendant shall pay Zhang the relevant amount of RMB 76300; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'non-compete restriction,compensation,departure'),

  ('lcase_016', '(2022) Hu 9015 Civil First-Instance No. 20555', 'Yun v. a consulting company, dispute over unlawful termination of labor contract', 'court_sh_jingan', 'labor dispute', 'unlawful termination of labor contract', '2022-09-08',
    'Plaintiff: Yun (employee); Defendant: a consulting company',
    'The company submitted no evidence of reassignment or training, and the court found the incompetence-based termination procedure unlawful.',
    'Yun joined the defendant in 2014 as a product operations staff member at a monthly salary of RMB 11250. The company terminated unilaterally without following the statutory procedure, and the court found the termination unlawful and awarded compensation. The company submitted no reassignment notice or training records.',
    'The company claimed the employee was incompetent but submitted no evidence of reassignment or training. Termination for incompetence presupposes that the employee remains incompetent after training or reassignment; the procedural requirement was not met.',
    'Termination on the ground of incompetence presupposes that the employee remains incompetent after training or reassignment.',
    '1. The defendant shall pay Yun the relevant amount of RMB 90000; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unlawful termination,compensation,unlawful procedure'),

  ('lcase_017', '(2022) Hu 9016 Civil First-Instance No. 20592', 'Su v. a catering company, dispute over annual leave', 'court_bj_haidian', 'labor dispute', 'annual leave', '2022-08-15',
    'Plaintiff: Su (employee); Defendant: a catering company',
    'The company unilaterally cleared the carried-over annual leave, and the court found this without basis and ordered compensation for the converted days.',
    'Su joined the defendant in 2013 as a customer-service specialist at a monthly salary of RMB 11600. The employee did not take annual leave for several consecutive years, and the court ordered payment of wages for untaken annual leave. The parties confirmed the prior year''s annual leave was carried over and then cleared.',
    'Annual leave may be arranged across years, but only with the employee''s consent. The company unilaterally carried over the prior year''s annual leave and then cleared it as expired; this has no basis, and the untaken days shall be converted into compensation.',
    'Carrying annual leave across years requires the employee''s consent; unilaterally clearing it has no basis.',
    '1. The defendant shall pay Su the relevant amount of RMB 104400; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'annual leave,wages for untaken annual leave,triple'),

  ('lcase_018', '(2022) Hu 9017 Civil First-Instance No. 20629', 'Pan v. an education company, dispute over social insurance', 'arb_bj_chaoyang', 'labor dispute', 'social insurance', '2022-07-22',
    'Plaintiff: Pan (employee); Defendant: an education company',
    'The parties agreed to substitute social insurance subsidies for enrollment, and the court found the agreement invalid.',
    'Pan joined the defendant in 2012 as a front-end engineer at a monthly salary of RMB 11950. The company failed to pay social insurance as required by law; the employee rescinded on that ground and claimed economic compensation. The company submitted records of social insurance subsidy payments.',
    'The parties agreed that the company would pay social insurance subsidies and the employee would pay the premiums himself; this agreement is invalid for violating mandatory legal provisions, and the company shall still enroll him as required by law and bear corresponding liability.',
    'An agreement to substitute social insurance subsidies for lawful enrollment is invalid.',
    '1. The defendant shall pay Pan the relevant amount of RMB 119500; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'social insurance,back payment,termination under pressure,Article 38'),

  ('lcase_019', '(2022) Hu 9018 Civil First-Instance No. 20666', 'Ge v. a financial company, dispute over work-related injury', 'court_sh_pudong', 'labor dispute', 'work-related injury', '2022-06-01',
    'Plaintiff: Ge (employee); Defendant: a financial company',
    'The employee was in a traffic accident on the way to or from work for which he was not primarily responsible, and the court found this constituted a work-related injury.',
    'Ge joined the defendant in 2020 as a finance specialist at a monthly salary of RMB 12300. The company stopped paying wages during the employee''s work-injury suspension period, and the court ordered back payment. The traffic police issued the accident responsibility determination.',
    'The employee sustained injury in a traffic accident on the way to or from work for which he was not primarily responsible, as confirmed by the traffic police responsibility determination; it shall be recognized as a work-related injury, and the company''s defense fails.',
    'An injury sustained in a traffic accident on the way to or from work for which the person is not primarily responsible shall be recognized as a work-related injury.',
    '1. The defendant shall pay Ge the relevant amount of RMB 24600; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'work-related injury,suspension period,wages'),

  ('lcase_020', '(2022) Hu 9019 Civil First-Instance No. 20703', 'Xi v. a trading company, labor arbitration dispute', 'court_sh_minhang', 'labor arbitration', 'labor arbitration', '2022-05-08',
    'Plaintiff: Xi (employee); Defendant: a trading company',
    'The amount in dispute exceeded the final-award limit, and the court found the company''s suit met the acceptance conditions.',
    'Xi joined the defendant in 2019 as a marketing manager at a monthly salary of RMB 12650. The parties reached a mediation settlement during arbitration, and the company paid a one-off compensation. During the proceedings, the local monthly minimum wage standard was checked.',
    'An arbitration award is final for disputes seeking labor remuneration not exceeding twelve months'' worth of the local monthly minimum wage. The amount in this case exceeded that limit, so the company''s suit met the acceptance conditions.',
    'A claim for labor remuneration exceeding twelve months'' worth of the local monthly minimum wage is not within the scope of a final award.',
    '1. The defendant shall pay Xi the relevant amount of RMB 37950; 2. The case acceptance fee shall be borne by the defendant.',
    'mediated', 'labor arbitration,mediation,one-off compensation'),

  ('lcase_021', '(2022) Hu 9020 Civil First-Instance No. 20740', 'Fan v. a technology company, dispute over overtime pay', 'court_bj_chaoyang', 'labor dispute', 'Overtime pay', '2022-04-15',
    'Plaintiff: Fan (employee); Defendant: a technology company',
    'The overtime pay base was lower than the contracted wage, and the court found the agreement invalid and adjusted the base.',
    'Fan joined the defendant in 2018 as a warehouse keeper at a monthly salary of RMB 13000. The employee worked extended overtime and the company failed to pay overtime in full; the court ordered back payment based on attendance records. The parties disagreed on the overtime pay base and each submitted wage-composition materials.',
    'The parties did not dispute the overtime facts; the dispute concerned the calculation base. The agreed overtime base was lower than the monthly wage agreed in the labor contract, and this agreement diminishes the employee''s statutory rights and is not adopted; the base shall be the normal working-hours wage.',
    'An agreement that the overtime pay base is lower than the wage agreed in the labor contract is invalid; the base shall be the normal working-hours wage.',
    '1. The defendant shall pay Fan the relevant amount of RMB 52000; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'overtime pay,extended overtime,attendance,standard working hours'),

  ('lcase_022', '(2022) Hu 9021 Civil First-Instance No. 20777', 'Peng v. an e-commerce company, dispute over economic compensation', 'court_sh_xuhui', 'labor dispute', 'Economic compensation', '2022-03-22',
    'Plaintiff: Peng (employee); Defendant: an e-commerce company',
    'The resignation application bore no personal signature, and the court found termination proposed by the employer and agreed upon by consultation.',
    'Peng joined the defendant in 2017 as a quality inspector at a monthly salary of RMB 13350. The company proposed termination by agreement, and the court ordered economic compensation according to years of service. The employee submitted nearly a year of bank salary statements and pay slips.',
    'The monthly wage base for economic compensation shall be computed as the average wage over the twelve months before termination, including bonuses and allowances. The company computed it using only the contracted base salary and did not include the quarterly bonus, making the base too low; it shall be adjusted.',
    'The economic compensation base shall be computed as the average wage over the twelve months before termination, including bonuses and allowances.',
    '1. The defendant shall pay Peng the relevant amount of RMB 66750; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'economic compensation,N,termination by agreement,years of service'),

  ('lcase_023', '(2022) Hu 9022 Civil First-Instance No. 20814', 'Lang v. a media company, dispute over failure to sign a written labor contract', 'court_sh_jingan', 'labor dispute', 'failure to sign a written labor contract', '2022-02-01',
    'Plaintiff: Lang (employee); Defendant: a media company',
    'The double-wage difference is subject to the one-year limitation period, and the court only upheld the months within the period.',
    'Lang joined the defendant in 2016 as an administrative assistant at a monthly salary of RMB 13700. Employment continued for more than one month without a written contract, and the court ordered payment of the double-wage difference. The parties each stated their views on the starting point of the limitation period for the double-wage difference.',
    'The double-wage difference is a statutory payment subject to the one-year limitation period, running from the day after the deadline for concluding the contract expired; the part exceeding the limitation period is not supported, and only the months within the period are upheld in this case.',
    'The double-wage difference is subject to the one-year limitation period, computed month by month; the part exceeding the period is not supported.',
    '1. The defendant shall pay Lang the relevant amount of RMB 82200; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unsigned labor contract,double wages,Article 82'),

  ('lcase_024', '(2022) Hu 9023 Civil First-Instance No. 20851', 'Lu v. a manufacturing company, dispute over withheld labor remuneration', 'court_bj_haidian', 'labor dispute', 'arrears of labor remuneration', '2022-01-08',
    'Plaintiff: Lu (employee); Defendant: a manufacturing company',
    'The company lowered the performance rating to zero without submitting assessment records, and the court found this a disguised deduction.',
    'Lu joined the defendant in 2015 as a data analyst at a monthly salary of RMB 14050. The company withheld wages without cause; the employee rescinded under pressure and claimed back payment, which the court upheld. The company failed to submit the performance assessment records for the period in question.',
    'Although performance pay is determined by the company''s assessment, the assessment process must have a basis. The company reduced the performance coefficient to zero without submitting assessment records, constituting a disguised deduction, and the amount shall be made up at the average performance level.',
    'Reducing the performance rating to zero without assessment records constitutes a disguised deduction, and the amount shall be made up at the average performance level.',
    '1. The defendant shall pay Lu the relevant amount of RMB 98350; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'wage arrears,unpaid wages,termination under pressure'),

  ('lcase_025', '(2021) Hu 9024 Civil First-Instance No. 20888', 'Wei v. a logistics company, dispute over non-compete restriction', 'arb_bj_chaoyang', 'labor dispute', 'non-compete restriction', '2021-12-15',
    'Plaintiff: Wei (employee); Defendant: a logistics company',
    'The employee worked in a basic customer-service position without access to trade secrets, and the court found the non-compete agreement exceeded the necessary scope.',
    'Wei joined the defendant in 2013 as a project manager at a monthly salary of RMB 14400. A non-compete restriction was agreed but no compensation was paid; the employee claimed compensation, and the court upheld it at its discretion. The employee''s job description stated his work was customer consultation and response.',
    'The personnel scope of a non-compete restriction is limited to senior management, senior technical personnel, and others with confidentiality obligations. The employee worked in a basic customer-service position without access to trade secrets, and setting a non-compete restriction on him exceeded the necessary scope.',
    'Setting a non-compete restriction on a basic-position employee who has no access to trade secrets exceeds the necessary scope.',
    '1. The defendant shall pay Wei the relevant amount of RMB 115200; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'non-compete restriction,compensation,departure'),

  ('lcase_026', '(2021) Hu 9025 Civil First-Instance No. 20925', 'Chang v. a consulting company, dispute over unlawful termination of labor contract', 'court_sh_pudong', 'labor dispute', 'unlawful termination of labor contract', '2021-11-22',
    'Plaintiff: Chang (employee); Defendant: a consulting company',
    'The company did not notify the trade union before the termination and did not remedy this, and the court found the termination unlawful.',
    'Chang joined the defendant in 2012 as a supply-chain specialist at a monthly salary of RMB 14750. The company terminated unilaterally without following the statutory procedure, and the court found the termination unlawful and awarded compensation. The company confirmed it did not notify the trade union before the termination.',
    'The reason for terminating a labor contract shall be notified to the trade union in advance. The company did not perform the notification procedure and had not remedied it even by the time of litigation; the termination is unlawful.',
    'Where a labor contract is terminated without prior notification to the trade union and without remedy, the termination is unlawful.',
    '1. The defendant shall pay Chang the relevant amount of RMB 132750; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unlawful termination,compensation,unlawful procedure'),

  ('lcase_027', '(2021) Hu 9026 Civil First-Instance No. 20962', 'Ma v. a catering company, dispute over annual leave', 'court_sh_minhang', 'labor dispute', 'annual leave', '2021-10-01',
    'Plaintiff: Ma (employee); Defendant: a catering company',
    'The employee''s years of service with the former employer should be accumulated, and the court adjusted the annual leave days accordingly.',
    'Ma joined the defendant in 2011 as a UI designer at a monthly salary of RMB 15100. The employee did not take annual leave for several consecutive years, and the court ordered payment of wages for untaken annual leave. The employee submitted the former employer''s social insurance payment records.',
    'An employee''s years of service with the same or different employers are computed cumulatively. The employee submitted the former employer''s social insurance payment records, and his cumulative years of service shall be found to be ten years, with annual leave of ten days.',
    'An employee''s years of service across different employers are computed cumulatively to determine annual leave days.',
    '1. The defendant shall pay Ma the relevant amount of RMB 151000; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'annual leave,wages for untaken annual leave,triple'),

  ('lcase_028', '(2021) Hu 9027 Civil First-Instance No. 20999', 'Miao v. an education company, dispute over social insurance', 'court_bj_chaoyang', 'labor dispute', 'social insurance', '2021-09-08',
    'Plaintiff: Miao (employee); Defendant: an education company',
    'The company had long declared the contribution base at the minimum standard, and the court found this insufficient payment.',
    'Miao joined the defendant in 2019 as a test engineer at a monthly salary of RMB 15450. The company failed to pay social insurance as required by law; the employee rescinded on that ground and claimed economic compensation. The employee submitted salary statements and the social insurance contribution base declaration forms.',
    'The employee''s rescission of the labor contract and claim for economic compensation on the ground that the company failed to pay social insurance as required by law is well-founded. Declaring the contribution base at the minimum standard rather than the actual wage over a long period constitutes insufficient payment.',
    'Declaring the contribution base at the minimum standard over a long period constitutes insufficient payment of social insurance premiums.',
    '1. The defendant shall pay Miao the relevant amount of RMB 30900; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'social insurance,back payment,termination under pressure,Article 38'),

  ('lcase_029', '(2021) Hu 9028 Civil First-Instance No. 21036', 'Feng v. a financial company, dispute over work-related injury', 'court_sh_xuhui', 'labor dispute', 'work-related injury', '2021-08-15',
    'Plaintiff: Feng (employee); Defendant: a financial company',
    'The company paid wages at the sick-leave standard during the suspension period, and the court ordered the wage difference made up.',
    'Feng joined the defendant in 2018 as a sales consultant at a monthly salary of RMB 15800. The company stopped paying wages during the employee''s work-injury suspension period, and the court ordered back payment. The parties did not dispute the start and end of the suspension period.',
    'During the suspension period, the original wages and benefits remain unchanged and are paid monthly by the employer. The company paid wages at the sick-leave standard during this period, and the difference shall be made up.',
    'During the suspension period, the original wages and benefits remain unchanged; where wages were paid at the sick-leave standard, the difference shall be made up.',
    '1. The defendant shall pay Feng the relevant amount of RMB 47400; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'work-related injury,suspension period,wages'),

  ('lcase_030', '(2021) Hu 9029 Civil First-Instance No. 21073', 'Hua v. a trading company, labor arbitration dispute', 'court_sh_jingan', 'labor arbitration', 'labor arbitration', '2021-07-22',
    'Plaintiff: Hua (employee); Defendant: a trading company',
    'The employee applied for arbitration by mail, and the court treated the postmark date as the date of application.',
    'Hua joined the defendant in 2017 as an HR specialist at a monthly salary of RMB 16150. The parties reached a mediation settlement during arbitration, and the company paid a one-off compensation. The employee submitted the mailing proof of the arbitration application.',
    'The employee submitted the arbitration application by mail, and the postmark date is the date of application. Computed on this basis the limitation period had not expired, and the company''s defense of expiration fails.',
    'Where an arbitration application is submitted by mail, the date of the postmark is the date of application.',
    '1. The defendant shall pay Hua the relevant amount of RMB 64600; 2. The case acceptance fee shall be borne by the defendant.',
    'mediated', 'labor arbitration,mediation,one-off compensation'),

  ('lcase_031', '(2021) Hu 9030 Civil First-Instance No. 21110', 'Cao v. a technology company, dispute over overtime pay', 'court_bj_haidian', 'labor dispute', 'Overtime pay', '2021-06-01',
    'Plaintiff: Cao (employee); Defendant: a technology company',
    'The employee worked on rest days without compensatory leave, and the court ordered back payment at the rest-day standard.',
    'Cao joined the defendant in 2016 as a product operations staff member at a monthly salary of RMB 16500. The employee worked extended overtime and the company failed to pay overtime in full; the court ordered back payment based on attendance records. The employee provided work group-chat and project-milestone records to prove rest-day attendance.',
    'The work group-chat records submitted by the employee and the project launch time corroborate that he worked on rest days. The company arranged no compensatory leave and paid no corresponding remuneration, so the amount shall be made up at the rest-day overtime standard.',
    'Where work is arranged on a rest day without compensatory leave, remuneration shall be paid at the statutory standard.',
    '1. The defendant shall pay Cao the relevant amount of RMB 82500; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'overtime pay,extended overtime,attendance,standard working hours'),

  ('lcase_032', '(2021) Hu 9031 Civil First-Instance No. 21147', 'Yan v. an e-commerce company, dispute over economic compensation', 'arb_bj_chaoyang', 'labor dispute', 'Economic compensation', '2021-05-08',
    'Plaintiff: Yan (employee); Defendant: an e-commerce company',
    'The company computed the compensation base using only the base salary, and the court held that bonuses and allowances should be included.',
    'Yan joined the defendant in 2015 as a customer-service specialist at a monthly salary of RMB 16850. The company proposed termination by agreement, and the court ordered economic compensation according to years of service. During the proceedings, the local average monthly wage of employees in the previous year was checked.',
    'Where the employee''s average monthly wage exceeds three times the local average monthly wage of employees in the previous year, compensation is paid at three times that amount, for no more than twelve years. The employee''s wage in this case did not reach that standard, so the cap rule does not apply.',
    'Where the monthly wage does not reach three times the local average, the triple cap and twelve-year limit do not apply.',
    '1. The defendant shall pay Yan the relevant amount of RMB 101100; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'economic compensation,N,termination by agreement,years of service'),

  ('lcase_033', '(2021) Hu 9032 Civil First-Instance No. 21184', 'Hua v. a media company, dispute over failure to sign a written labor contract', 'court_sh_pudong', 'labor dispute', 'failure to sign a written labor contract', '2021-04-15',
    'Plaintiff: Hua (employee); Defendant: a media company',
    'The employee was the HR supervisor responsible for contract signing, and the court did not support his double-wage claim.',
    'Hua joined the defendant in 2014 as a front-end engineer at a monthly salary of RMB 17200. Employment continued for more than one month without a written contract, and the court ordered payment of the double-wage difference. The employee''s job description stated he was responsible for signing contracts for all staff.',
    'The employee was the company''s HR supervisor responsible for handling contract signing for all staff; he was at fault for not concluding a written contract with himself, so his double-wage difference claim is not supported.',
    'Where the HR personnel responsible for contract signing management failed to conclude a contract with himself, the double-wage difference claim is not supported.',
    '1. The defendant shall pay Hua the relevant amount of RMB 120400; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unsigned labor contract,double wages,Article 82'),

  ('lcase_034', '(2021) Hu 9033 Civil First-Instance No. 21221', 'Jin v. a manufacturing company, dispute over withheld labor remuneration', 'court_sh_minhang', 'labor dispute', 'arrears of labor remuneration', '2021-03-22',
    'Plaintiff: Jin (employee); Defendant: a manufacturing company',
    'The company refused to pay the final month''s wages for failure to complete the handover, and the court found this no ground for refusal.',
    'Jin joined the defendant in 2013 as a finance specialist at a monthly salary of RMB 17550. The company withheld wages without cause; the employee rescinded under pressure and claimed back payment, which the court upheld. The parties confirmed the work handover had not been completed at departure.',
    'The company refused to pay the final month''s wages on the ground that the work handover had not been completed, but the wage payment obligation and the handover obligation are not reciprocal obligations, so payment may not be refused on that ground.',
    'The wage payment obligation and the work handover obligation are not reciprocal obligations, so wages may not be refused on the ground of an incomplete handover.',
    '1. The defendant shall pay Jin the relevant amount of RMB 140400; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'wage arrears,unpaid wages,termination under pressure'),

  ('lcase_035', '(2021) Hu 9034 Civil First-Instance No. 21258', 'Wei v. a logistics company, dispute over non-compete restriction', 'court_bj_chaoyang', 'labor dispute', 'non-compete restriction', '2021-02-01',
    'Plaintiff: Wei (employee); Defendant: a logistics company',
    'The two employers'' actual businesses and customer groups differ, and the court found they do not constitute competing businesses of the same kind.',
    'Wei joined the defendant in 2012 as a marketing manager at a monthly salary of RMB 17900. A non-compete restriction was agreed but no compensation was paid; the employee claimed compensation, and the court upheld it at its discretion. During the proceedings, the actual businesses and customer composition of the two employers were compared.',
    'Although the new employer the employee joined has a business scope overlapping the former employer''s, the actual business fields and customer groups differ, so they do not constitute competing businesses of the same kind, and the liquidated damages claim is not supported.',
    'Where business scopes overlap but the actual business fields and customer groups differ, they do not constitute competing businesses of the same kind.',
    '1. The defendant shall pay Wei the relevant amount of RMB 161100; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'non-compete restriction,compensation,departure'),

  ('lcase_036', '(2021) Hu 9035 Civil First-Instance No. 21295', 'Tao v. a consulting company, dispute over unlawful termination of labor contract', 'court_sh_xuhui', 'labor dispute', 'unlawful termination of labor contract', '2021-01-08',
    'Plaintiff: Tao (employee); Defendant: a consulting company',
    'The employee was pregnant and the company terminated her citing operational adjustment, and the court found the termination invalid.',
    'Tao joined the defendant in 2011 as a warehouse keeper at a monthly salary of RMB 18250. The company terminated unilaterally without following the statutory procedure, and the court found the termination unlawful and awarded compensation. The employee submitted the medical proof of pregnancy examination.',
    'The employee was pregnant, and the company rescinded the labor contract citing operational adjustment, violating the special protection for female employees during the three periods; the termination is invalid.',
    'A pregnant female employee may not be terminated on the ground of operational adjustment.',
    '1. The defendant shall pay Tao the relevant amount of RMB 182500; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unlawful termination,compensation,unlawful procedure'),

  ('lcase_037', '(2020) Hu 9036 Civil First-Instance No. 21332', 'Jiang v. a catering company, dispute over annual leave', 'court_sh_jingan', 'labor dispute', 'annual leave', '2020-12-15',
    'Plaintiff: Jiang (employee); Defendant: a catering company',
    'The company had already paid wages normally, and the court found only the double daily wage portion need be paid additionally.',
    'Jiang joined the defendant in 2018 as a quality inspector at a monthly salary of RMB 18600. The employee did not take annual leave for several consecutive years, and the court ordered payment of wages for untaken annual leave. The parties did not dispute that wages for the normal working period had been paid.',
    'The remuneration for untaken annual leave includes the portion the employer pays as wages for the normal working period; where the company has already paid wages normally, it need only pay the double daily wage portion additionally.',
    'Where the employer has already paid wages normally, only the double daily wage portion need be paid additionally for untaken annual leave.',
    '1. The defendant shall pay Jiang the relevant amount of RMB 37200; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'annual leave,wages for untaken annual leave,triple'),

  ('lcase_038', '(2020) Hu 9037 Civil First-Instance No. 21369', 'Qi v. an education company, dispute over social insurance', 'court_bj_haidian', 'labor dispute', 'social insurance', '2020-11-22',
    'Plaintiff: Qi (employee); Defendant: an education company',
    'The employee requested an order to back-pay social insurance premiums, and the court found this outside its scope of acceptance and dismissed it.',
    'Qi joined the defendant in 2017 as an administrative assistant at a monthly salary of RMB 18950. The company failed to pay social insurance as required by law; the employee rescinded on that ground and claimed economic compensation. The employee also raised a back-payment request during arbitration.',
    'The back-payment of social insurance premiums falls within the authority of the social insurance collection agency; the portion in which the employee seeks a direct judicial order to back-pay the premiums is outside the people''s court''s scope of acceptance and is dismissed.',
    'A request for an order to back-pay social insurance premiums is outside the people''s court''s scope of acceptance.',
    '1. The defendant shall pay Qi the relevant amount of RMB 56850; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'social insurance,back payment,termination under pressure,Article 38'),

  ('lcase_039', '(2020) Hu 9038 Civil First-Instance No. 21406', 'Xie v. a financial company, dispute over work-related injury', 'arb_bj_chaoyang', 'labor dispute', 'work-related injury', '2020-10-01',
    'Plaintiff: Xie (employee); Defendant: a financial company',
    'The company claimed the employee operated improperly, and the court found this did not affect work-injury recognition.',
    'Xie joined the defendant in 2016 as a data analyst at a monthly salary of RMB 19300. The company stopped paying wages during the employee''s work-injury suspension period, and the court ordered back payment. The company submitted the safety operating procedures and the training sign-in sheets.',
    'The company argued the injury resulted from the employee''s own improper operation, but apart from intentional crime, intoxication or drug use, self-harm, or suicide, improper operation does not affect work-injury recognition.',
    'Apart from intentional crime, intoxication or drug use, self-harm, or suicide, improper operation does not affect work-injury recognition.',
    '1. The defendant shall pay Xie the relevant amount of RMB 77200; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'work-related injury,suspension period,wages'),

  ('lcase_040', '(2020) Hu 9039 Civil First-Instance No. 21443', 'Zou v. a trading company, labor arbitration dispute', 'court_sh_pudong', 'labor arbitration', 'labor arbitration', '2020-09-08',
    'Plaintiff: Zou (employee); Defendant: a trading company',
    'Both parties sued against the arbitration award, and the court tried all matters in dispute.',
    'Zou joined the defendant in 2015 as a project manager at a monthly salary of RMB 19650. The parties reached a mediation settlement during arbitration, and the company paid a one-off compensation. Both parties sued against the arbitration award.',
    'Where a party sues against an arbitration award, the award has no legal effect, and the people''s court shall try all matters in dispute without being bound by the award.',
    'Where a party sues against an arbitration award, the people''s court shall try all matters in dispute.',
    '1. The defendant shall pay Zou the relevant amount of RMB 98250; 2. The case acceptance fee shall be borne by the defendant.',
    'mediated', 'labor arbitration,mediation,one-off compensation'),

  ('lcase_041', '(2020) Hu 9040 Civil First-Instance No. 21480', 'Yu v. a technology company, dispute over overtime pay', 'court_sh_minhang', 'labor dispute', 'Overtime pay', '2020-08-15',
    'Plaintiff: Yu (employee); Defendant: a technology company',
    'The company''s shift schedule conflicted with the clock-in records, and the adverse consequence of the burden of proof is borne by the employer.',
    'Yu joined the defendant in 2014 as a supply-chain specialist at a monthly salary of RMB 20000. The employee worked extended overtime and the company failed to pay overtime in full; the court ordered back payment based on attendance records. During the proceedings, the original exported data from the company''s attendance system was retrieved.',
    'On allocation of the burden of proof for extended overtime, the employee made a prima facie showing and the company submitted no contrary evidence to rebut it; the claimed overtime hours are confirmed, but the part beyond the clock-in records is not supported.',
    'Where the employee has made a prima facie showing and the employer submits no contrary evidence, the overtime facts are confirmed.',
    '1. The defendant shall pay Yu the relevant amount of RMB 120000; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'overtime pay,extended overtime,attendance,standard working hours'),

  ('lcase_042', '(2020) Hu 9041 Civil First-Instance No. 21517', 'Bai v. an e-commerce company, dispute over economic compensation', 'court_bj_chaoyang', 'labor dispute', 'Economic compensation', '2020-07-22',
    'Plaintiff: Bai (employee); Defendant: an e-commerce company',
    'The company sought a reduction of compensation citing operating difficulties, and the court found this not a statutory ground for exemption.',
    'Bai joined the defendant in 2013 as a UI designer at a monthly salary of RMB 20350. The company proposed termination by agreement, and the court ordered economic compensation according to years of service. The company submitted financial statements to claim operating difficulties.',
    'The company sought a reduction of economic compensation on the ground of operating difficulties, but the business situation is not a statutory ground for exemption from paying economic compensation, and its defense fails.',
    'Operating difficulties are not a statutory ground for exemption from paying economic compensation.',
    '1. The defendant shall pay Bai the relevant amount of RMB 142450; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'economic compensation,N,termination by agreement,years of service'),

  ('lcase_043', '(2020) Hu 9042 Civil First-Instance No. 21554', 'Shui v. a media company, dispute over failure to sign a written labor contract', 'court_sh_xuhui', 'labor dispute', 'failure to sign a written labor contract', '2020-06-01',
    'Plaintiff: Shui (employee); Defendant: a media company',
    'The parties confirmed the essential terms electronically, and the court deemed a written contract concluded.',
    'Shui joined the defendant in 2012 as a test engineer at a monthly salary of RMB 20700. Employment continued for more than one month without a written contract, and the court ordered payment of the double-wage difference. The company submitted the confirmation records from the electronic signing platform.',
    'Although the parties did not conclude a written contract, they confirmed the essential terms including position, remuneration, and term electronically, and the employee acknowledged them; a written contract may be deemed concluded.',
    'Where the essential terms are confirmed electronically and acknowledged by the employee, a written labor contract may be deemed concluded.',
    '1. The defendant shall pay Shui the relevant amount of RMB 165600; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unsigned labor contract,double wages,Article 82'),

  ('lcase_044', '(2020) Hu 9043 Civil First-Instance No. 21591', 'Dou v. a manufacturing company, dispute over withheld labor remuneration', 'court_sh_jingan', 'labor dispute', 'arrears of labor remuneration', '2020-05-08',
    'Plaintiff: Dou (employee); Defendant: a manufacturing company',
    'The sales policy did not make payment conditional on collection, and the court ordered payment of the commission.',
    'Dou joined the defendant in 2011 as a sales consultant at a monthly salary of RMB 21050. The company withheld wages without cause; the employee rescinded under pressure and claimed back payment, which the court upheld. The employee submitted the sales policy documents and order details.',
    'The commission claimed by the employee had met the payment condition under the sales policy; the company delayed payment citing that the order had not been collected, but the policy did not make payment conditional on collection, so it shall be paid.',
    'Where the sales policy does not make collection a condition for paying commission, payment may not be deferred on the ground that collection has not occurred.',
    '1. The defendant shall pay Dou the relevant amount of RMB 189450; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'wage arrears,unpaid wages,termination under pressure'),

  ('lcase_045', '(2020) Hu 9044 Civil First-Instance No. 21628', 'Zhang v. a logistics company, dispute over non-compete restriction', 'court_bj_haidian', 'labor dispute', 'non-compete restriction', '2020-04-15',
    'Plaintiff: Zhang (employee); Defendant: a logistics company',
    'The agreed three-year non-compete term exceeded the statutory ceiling, and the court found it as two years.',
    'Zhang joined the defendant in 2010 as an HR specialist at a monthly salary of RMB 21400. A non-compete restriction was agreed but no compensation was paid; the employee claimed compensation, and the court upheld it at its discretion. The parties did not dispute the agreed three-year term.',
    'The non-compete term was agreed as three years, exceeding the statutory two-year ceiling; the excess is invalid and it is found as two years. During this period the company paid monthly compensation, and the employee shall perform the obligation.',
    'Where the non-compete term exceeds two years, the excess is invalid and it is found as two years.',
    '1. The defendant shall pay Zhang the relevant amount of RMB 214000; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'non-compete restriction,compensation,departure'),

  ('lcase_046', '(2020) Hu 9045 Civil First-Instance No. 21665', 'Yun v. a consulting company, dispute over unlawful termination of labor contract', 'arb_bj_chaoyang', 'labor dispute', 'unlawful termination of labor contract', '2020-03-22',
    'Plaintiff: Yun (employee); Defendant: a consulting company',
    'The disciplinary record was made after the termination, and the court found it could not prove a statutory ground existed at the time of termination.',
    'Yun joined the defendant in 2018 as a product operations staff member at a monthly salary of RMB 21750. The company terminated unilaterally without following the statutory procedure, and the court found the termination unlawful and awarded compensation. The disciplinary record submitted by the company was dated after the termination notice.',
    'The disciplinary record submitted by the company was made after the termination and cannot prove a statutory ground existed at the time of termination; the termination is unlawful and compensation shall be paid.',
    'A disciplinary record made after termination cannot prove a statutory ground existed at the time of termination.',
    '1. The defendant shall pay Yun the relevant amount of RMB 43500; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unlawful termination,compensation,unlawful procedure'),

  ('lcase_047', '(2020) Hu 9046 Civil First-Instance No. 21702', 'Su v. a catering company, dispute over annual leave', 'court_sh_pudong', 'labor dispute', 'annual leave', '2020-02-01',
    'Plaintiff: Su (employee); Defendant: a catering company',
    'The company did not arrange leave without obtaining consent, and the court ordered remuneration made up at the standard.',
    'Su joined the defendant in 2017 as a customer-service specialist at a monthly salary of RMB 22100. The employee did not take annual leave for several consecutive years, and the court ordered payment of wages for untaken annual leave. The company claimed leave was not arranged due to a tight project schedule.',
    'Where a company does not arrange annual leave due to production needs, it shall obtain the employee''s consent and pay remuneration at the standard. In this case the company neither obtained consent nor paid, and the amount shall be made up.',
    'Where annual leave is not arranged due to production needs, the employee''s consent shall be obtained and remuneration paid at the standard.',
    '1. The defendant shall pay Su the relevant amount of RMB 66300; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'annual leave,wages for untaken annual leave,triple'),

  ('lcase_048', '(2020) Hu 9047 Civil First-Instance No. 21739', 'Pan v. an education company, dispute over social insurance', 'court_sh_minhang', 'labor dispute', 'social insurance', '2020-01-08',
    'Plaintiff: Pan (employee); Defendant: an education company',
    'The company had not paid work-injury insurance, and the court ordered it to bear the costs at the work-injury benefit standard.',
    'Pan joined the defendant in 2016 as a front-end engineer at a monthly salary of RMB 22450. The company failed to pay social insurance as required by law; the employee rescinded on that ground and claimed economic compensation. The parties confirmed the company had not enrolled in work-injury insurance when the accident occurred.',
    'The company failed to pay work-injury insurance for the employee; after the work-related injury occurred, the company shall bear all costs at the work-injury insurance benefit standard.',
    'Where work-injury insurance has not been paid, the employer shall bear the costs at the work-injury insurance benefit standard.',
    '1. The defendant shall pay Pan the relevant amount of RMB 89800; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'social insurance,back payment,termination under pressure,Article 38'),

  ('lcase_049', '(2019) Hu 9048 Civil First-Instance No. 21776', 'Ge v. a financial company, dispute over work-related injury', 'court_bj_chaoyang', 'labor dispute', 'work-related injury', '2019-12-15',
    'Plaintiff: Ge (employee); Defendant: a financial company',
    'The company had not enrolled in work-injury insurance, and the court ordered it to bear both subsidies.',
    'Ge joined the defendant in 2014 as a finance specialist at a monthly salary of RMB 22800. The company stopped paying wages during the employee''s work-injury suspension period, and the court ordered back payment. The parties confirmed that work-injury insurance enrollment had not been handled when the accident occurred.',
    'The one-off disability employment subsidy is paid by the employer, and the one-off work-injury medical subsidy is paid by the work-injury insurance fund. Where the company has not enrolled in the insurance, it shall bear both.',
    'Where the employer has not enrolled in work-injury insurance, it shall bear both the one-off disability employment subsidy and the medical subsidy.',
    '1. The defendant shall pay Ge the relevant amount of RMB 114000; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'work-related injury,suspension period,wages'),

  ('lcase_050', '(2019) Hu 9049 Civil First-Instance No. 21813', 'Xi v. a trading company, labor arbitration dispute', 'court_sh_xuhui', 'labor arbitration', 'labor arbitration', '2019-11-22',
    'Plaintiff: Xi (employee); Defendant: a trading company',
    'The employee submitted reminder emails proving interruption, and the court recomputed the arbitration limitation period.',
    'Xi joined the defendant in 2013 as a marketing manager at a monthly salary of RMB 23150. The parties reached a mediation settlement during arbitration, and the company paid a one-off compensation. The employee submitted the reminder emails sent to the company.',
    'The limitation period is interrupted when one party asserts its rights against the other and runs anew from the interruption. The reminder emails submitted by the employee can prove the interruption.',
    'The limitation period is interrupted when one party asserts its rights against the other and runs anew from the interruption.',
    '1. The defendant shall pay Xi the relevant amount of RMB 138900; 2. The case acceptance fee shall be borne by the defendant.',
    'mediated', 'labor arbitration,mediation,one-off compensation'),

  ('lcase_051', '(2019) Hu 9050 Civil First-Instance No. 21850', 'Fan v. a technology company, dispute over overtime pay', 'court_sh_jingan', 'labor dispute', 'Overtime pay', '2019-10-01',
    'Plaintiff: Fan (employee); Defendant: a technology company',
    'The company had lawfully filed the comprehensive working hours system, and the court reduced the overtime hours accordingly.',
    'Fan joined the defendant in 2012 as a warehouse keeper at a monthly salary of RMB 23500. The employee worked extended overtime and the company failed to pay overtime in full; the court ordered back payment based on attendance records. The company submitted the administrative filing receipt for the comprehensive working hours system.',
    'The company applied the comprehensive working hours system with lawful filing, so only the hours exceeding the total for the computation cycle constitute extended overtime; the employee''s daily cumulative calculation was not adopted, and the amount was reduced accordingly.',
    'Where the comprehensive working hours system is lawfully filed, only the hours exceeding the total for the cycle are recognized as extended overtime.',
    '1. The defendant shall pay Fan the relevant amount of RMB 164500; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'overtime pay,extended overtime,attendance,standard working hours'),

  ('lcase_052', '(2019) Hu 9051 Civil First-Instance No. 21887', 'Peng v. an e-commerce company, dispute over economic compensation', 'court_bj_haidian', 'labor dispute', 'Economic compensation', '2019-09-08',
    'Plaintiff: Peng (employee); Defendant: an e-commerce company',
    'The company reduced the terms for renewal, causing the employee to decline, and the court still ordered economic compensation.',
    'Peng joined the defendant in 2011 as a quality inspector at a monthly salary of RMB 23850. The company proposed termination by agreement, and the court ordered economic compensation according to years of service. The parties submitted comparison materials on the renewal terms.',
    'Where, after expiry of the labor contract, the company maintains or improves the original terms for renewal but the employee declines to renew, the company need not pay economic compensation. In this case the company reduced the position and pay terms, so compensation is still payable.',
    'Where the employer reduces the original terms for renewal and the employee declines, economic compensation shall still be paid.',
    '1. The defendant shall pay Peng the relevant amount of RMB 190800; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'economic compensation,N,termination by agreement,years of service'),

  ('lcase_053', '(2019) Hu 9052 Civil First-Instance No. 21924', 'Lang v. a media company, dispute over failure to sign a written labor contract', 'arb_bj_chaoyang', 'labor dispute', 'failure to sign a written labor contract', '2019-08-15',
    'Plaintiff: Lang (employee); Defendant: a media company',
    'Employment continued for more than one year without a contract, and the court found an open-ended labor contract deemed concluded.',
    'Lang joined the defendant in 2010 as an administrative assistant at a monthly salary of RMB 24200. Employment continued for more than one month without a written contract, and the court ordered payment of the double-wage difference. The parties confirmed the employment relationship had lasted more than one year.',
    'Where no written contract is concluded even after one year of employment, an open-ended labor contract is deemed concluded, and thereafter the double-wage difference is no longer computed; the company shall belatedly conclude the contract.',
    'Where no written contract is concluded after one year of employment, an open-ended labor contract is deemed concluded.',
    '1. The defendant shall pay Lang the relevant amount of RMB 217800; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'unsigned labor contract,double wages,Article 82'),

  ('lcase_054', '(2019) Hu 9053 Civil First-Instance No. 21961', 'Lu v. a manufacturing company, dispute over withheld labor remuneration', 'court_sh_pudong', 'labor dispute', 'arrears of labor remuneration', '2019-07-22',
    'Plaintiff: Lu (employee); Defendant: a manufacturing company',
    'Where work is suspended for more than one wage payment cycle, the court determined living expenses at 80 percent of the minimum wage.',
    'Lu joined the defendant in 2009 as a data analyst at a monthly salary of RMB 24550. The company withheld wages without cause; the employee rescinded under pressure and claimed back payment, which the court upheld. The parties did not dispute the start and end of the suspension.',
    'The parties disputed the wage standard during the suspension period. Where suspension is within one wage payment cycle, wages shall be paid as agreed in the contract; beyond the cycle, living expenses shall be paid at 80 percent of the local minimum wage.',
    'Where work is suspended for more than one wage payment cycle, living expenses shall be paid at 80 percent of the local minimum wage.',
    '1. The defendant shall pay Lu the relevant amount of RMB 245500; 2. The case acceptance fee shall be borne by the defendant.',
    'upheld', 'wage arrears,unpaid wages,termination under pressure'),

  ('lcase_055', '(2019) Hu 9054 Civil First-Instance No. 21998', 'Wei v. a logistics company, dispute over non-compete restriction', 'court_sh_minhang', 'labor dispute', 'non-compete restriction', '2019-06-01',
    'Plaintiff: Wei (employee); Defendant: a logistics company',
    'The agreed liquidated damages were grossly excessive relative to actual loss, and the court reduced them at its discretion.',
    'Wei joined the defendant in 2017 as a project manager at a monthly salary of RMB 24900. A non-compete restriction was agreed but no compensation was paid; the employee claimed compensation, and the court upheld it at its discretion. The parties did not dispute that Wei did not join a competing unit after departure.',
    'Where the employee has actually performed the non-compete obligation, the employer shall still pay compensation even if no compensation standard was agreed. The standard may be computed monthly at 30 percent of the employee''s average wage over the twelve months before departure, or at the local minimum wage if lower.',
    'Where the employee has actually performed the non-compete obligation and no compensation standard was agreed, compensation may be paid monthly at 30 percent of the average wage over the twelve months before departure.',
    '1. The defendant shall pay Wei the relevant amount of RMB 49800; 2. The case acceptance fee shall be borne by the defendant.',
    'partially upheld', 'non-compete restriction,compensation,departure');

