-- ── Task-specific equity dispute legal skeleton: authentic Civil Code provisions + anonymized case summaries with case numbers redacted ──
INSERT INTO statutes (statute_id, name, short_name, issuer, effective_date, status, summary) VALUES
  ('stat_cc', 'Civil Code of the People''s Republic of China', 'Civil Code', 'National People''s Congress', '2021-01-01', 'currently effective',
   'This task uses only the contract performance, standard terms, and unconscionability rules to analyze the equity plan agreement; the market price is factual evidence, not a uniform formula that automatically substitutes for the contract price.');

INSERT INTO statute_articles (article_id, statute_id, article_no, seq, heading, text) VALUES
  ('art_cc_509', 'stat_cc', 'Article 509', 509, 'Performance of contract and the principle of good faith',
   'The parties shall perform their obligations in full in accordance with the agreement. The parties shall follow the principle of good faith and, in light of the nature and purpose of the contract and the course of dealing, perform obligations such as notification, assistance, and confidentiality. In the course of performing the contract, the parties shall avoid wasting resources, polluting the environment, and damaging the ecology.'),
  ('art_cc_496', 'stat_cc', 'Article 496', 496, 'Duty to draw attention to and explain standard terms',
   'Where a contract is concluded using standard terms, the party supplying the standard terms shall determine the parties'' rights and obligations in accordance with the principle of fairness, shall draw the other party''s attention in a reasonable manner to terms that materially affect the other party, such as terms excluding or limiting its liability, and shall explain such terms upon the other party''s request. Where the party supplying the standard terms fails to perform the duty to draw attention to or explain the terms, so that the other party fails to notice or understand the terms that materially affect its interests, the other party may claim that such terms do not form part of the contract.'),
  ('art_cc_497', 'stat_cc', 'Article 497', 497, 'Circumstances rendering standard terms invalid',
   'A standard term is invalid under any of the following circumstances: it falls within the invalidity situations provided in Section 3 of Chapter 6 of Part One of this Law and Article 506 of this Law; the party supplying the standard term unreasonably excludes or reduces its own liability, increases the other party''s liability, or restricts the other party''s principal rights; or the party supplying the standard term excludes the other party''s principal rights.'),
  ('art_cc_151', 'stat_cc', 'Article 151', 151, 'Unconscionability and rescission',
   'Where one party takes advantage of the other party''s state of distress or lack of judgment, such that the civil juristic act is obviously unfair when formed, the injured party has the right to request a people''s court or an arbitration institution to rescind it.');

INSERT INTO cases (case_id, case_number, title, court_id, case_type, cause, judgment_date, parties, summary, facts, reasoning, holding, ruling, outcome, keywords) VALUES
  ('case_rsu_001', 'case number redacted (anonymized summary - RSU-01)', 'Anonymized summary of a dispute over performance of the vested-share settlement clause upon departure', 'court_sh_pudong', 'contract dispute', 'restricted stock buyback', '2025-10-23',
   'Employee A; a technology company',
   'The adjudication reviewed the settlement obligation in light of the share plan documents signed by both parties, the vested quantity, and the base-date price evidence; it did not hold in the abstract that all equity held by departing employees is uniformly settled at the closing price.',
   'The plan documents expressly provided that vested shares would be settled at a verifiable market price on the departure base date; the company later proposed a scheme using an internal fixed price, and the employee submitted the grant confirmation, brokerage holdings, and contemporaneous market data.',
   'The focus of review was whether the original agreement was formed and should be fully performed in accordance with the principle of good faith. The market closing price became calculation evidence because the contract expressly referenced it; had the contract lacked such a term, the determination would still require consideration of the nature of the plan, the communication records, and other evidence, and a uniform price formula could not be applied directly.',
   'Under the specific contract in that case, the reference amount payable was verified by multiplying the vested quantity by the contractually agreed base-date market price; salary records and years of service were not treated as the basis for valuing the equity.',
   'After taking into account amounts already paid, the claim for the contractually supported price difference was partially upheld.', 'partially upheld',
   'case number redacted,anonymized summary,vested,contract performance,base date,market price'),
  ('case_rsu_002', 'case number redacted (anonymized summary - RSU-02)', 'Anonymized summary of a dispute over the duty to draw attention to and explain a low-price settlement standard term', 'court_sh_no1', 'contract dispute', 'restricted stock buyback', '2025-11-26',
   'Employee B; a data company',
   'The adjudication reviewed whether the company performed the duty to draw attention to and explain the low-price settlement standard term that materially affected the vested equity, and determined the validity of the term in light of the signing process, negotiation records, and pricing evidence.',
   'The company argued the employee had ticked acceptance of the internal-price term; the employee argued the term was buried in an annex and never brought to his attention. Both parties submitted version records, receipt logs, emails, and market data.',
   'A template signature alone does not automatically resolve the notice-and-explanation dispute; but neither does a market price markedly higher than the internal price automatically invalidate the term. The court should separately examine whether the term became part of the contract, whether it unreasonably excluded liability or restricted principal rights, and the probative value of the price evidence.',
   'The validity of the standard term and the amount payable must be determined under Articles 496 and 497 of the Civil Code and the specific evidence; the market price is an important reference, not an automatic adjudication rule.',
   'Remanded for further proceedings in light of the notice-and-explanation evidence and the original plan text.', 'other',
   'case number redacted,anonymized summary,standard terms,notice and explanation,market evidence'),
  ('case_rsu_003', 'case number redacted (anonymized summary - RSU-03)', 'Anonymized summary of a claim involving time-limited signing and unconscionability', 'court_sh_minhang', 'contract dispute', 'validity of agreement', '2025-12-04',
   'Employee C; a platform company',
   'The employee was required to sign a settlement agreement under a time limit while facing departure and family pressure; the adjudication did not rescind the agreement merely because of a price difference, but instead examined exploitation of distress, information disclosure, the negotiation process, and whether the rights and obligations were significantly imbalanced.',
   'The company tied payment to the signing of a new non-compete term and imposed a short deadline; the employee retained the reminder emails, the original grant rules, and consultation records.',
   'Unconscionability requires examining whether, at the time of formation, there was exploitation of distress or lack of judgment and whether the outcome was significantly imbalanced. Merely deeming the price unfavorable after the fact is insufficient for rescission; persistent pressure to sign, concealment of material terms, and the bundling of additional obligations may serve as combined evidence.',
   'Whether the agreement is to be rescinded or adjusted must be determined under Article 151 of the Civil Code in light of the formation process, and a particular result cannot be presumed.',
   'The claims supported by evidence were upheld, and the remainder was dismissed.', 'partially upheld',
   'case number redacted,anonymized summary,unconscionability,time-limited pressure to sign,validity of agreement');

INSERT INTO citations (citation_id, case_id, target_type, target_id, label) VALUES
  ('cit_rsu_001', 'case_rsu_001', 'article', 'art_cc_509', 'performance in full as agreed'),
  ('cit_rsu_002', 'case_rsu_001', 'article', 'art_cc_496', 'notice and explanation of terms of material interest'),
